'use client'
import toast from 'react-hot-toast';
import React from 'react';
import { useTimeline } from '@/context/TimelineContext';

const CheckInbuttons = ({friend}) => {
    const {addEntry} = useTimeline()
    const handleclick =(type) =>{
        addEntry({
        id: Data.now(),
        type,
        title : `${type} with ${friend.name}`,
        date: new Date().toLocaleDataString()



        })
        toast.success(`${type} logged with ${friend.name}`)
    }
    return (
       <div className="grid grid-cols-3 gap-3">
      <button onClick={() => handleClick("Call")}>Call</button>
      <button onClick={() => handleClick("Text")}>Text</button>
      <button onClick={() => handleClick("Video")}>Video</button>
    </div>
    );
};

export default CheckInbuttons;